const $=id=>document.getElementById(id);let mode='major',selected=0;
Music.keys.forEach(k=>{const option=document.createElement('option');option.value=k;option.textContent=`${Music.pretty(k)} — ${Music.full(k)}`;$('key').append(option);});
function render(){const f=Music.field($('key').value,mode),label=mode==='major'?'maior':'menor natural';$('summary-name').textContent=Music.full(f.key)+' '+label;$('scale-title').textContent='Escala de '+Music.full(f.key)+' '+label;const relative=f.notes[mode==='major'?5:2];$('relative').textContent='Relativa: '+Music.full(relative)+(mode==='major'?' menor':' maior');$('major').setAttribute('aria-pressed',mode==='major');$('minor').setAttribute('aria-pressed',mode==='minor');$('scale').innerHTML=f.notes.concat(f.notes[0]).map((n,i)=>`<div class="scale-note ${i===0||i===7?'tonic-note':''}"><small>${i===7?'8':i+1}º</small><strong>${Music.pretty(n)}</strong><span>${Music.full(n)}</span></div>${i<7?`<div class="interval ${f.steps[i]===1?'half':''}"><span>${f.steps[i]===1?'½':'1'}</span><small>${f.steps[i]===1?'semitom':'tom'}</small></div>`:''}`).join('');$('pattern').textContent=f.steps.map(x=>x===2?'tom':'semitom').join(' · ');$('chords').innerHTML=f.chords.map((c,i)=>`<button class="chord ${i===selected?'selected':''}" data-degree="${i}" aria-pressed="${i===selected}"><span>${c.roman}</span><strong>${Music.pretty(c.symbol)}</strong><small>${quality(c)}</small>${Guitar.diagram(c.notes,c.symbol)}<div>${c.notes.map(Music.pretty).join(' · ')}</div></button>`).join('');$('chords').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.degree);render();});const c=f.chords[selected];$('degree-label').textContent=`GRAU ${c.roman} / ${selected+1}º ACORDE`;$('big-chord').textContent=Music.pretty(c.symbol);$('chord-quality').textContent=Music.full(c.root)+' '+quality(c).toLowerCase();$('base-notes').innerHTML=c.notes.map(n=>`<span>${Music.pretty(n)}</span>`).join('');const vs=Music.variations(f,selected);$('variation-count').textContent=vs.length+' formas';$('variations').innerHTML=vs.map(v=>`<div class="variation"><div><strong>${Music.pretty(v.symbol)}</strong><span class="status ${v.inside?'':'outside'}" title="${v.inside?'Todas as notas pertencem à escala':'Há notas fora da escala'}">${v.inside?'No tom':'Fora do tom'}</span></div><p>${v.label}</p>${Guitar.diagram(v.notes,v.symbol)}<span class="voicing">${v.notes.map(Music.pretty).join(' · ')}</span></div>`).join('');$('inversions').innerHTML=[0,1,2].map(i=>`<div><small>${['Fundamental','1ª inversão','2ª inversão'][i]}</small><strong>${Music.pretty(c.symbol)}${i?'/'+Music.pretty(c.notes[i]):''}</strong>${Guitar.diagram(c.notes,c.symbol+(i?'/'+c.notes[i]:''),c.notes[i])}<span>${c.notes.slice(i).concat(c.notes.slice(0,i)).map(Music.pretty).join(' · ')}</span></div>`).join('');}
function quality(c){return {major:'Maior',minor:'Menor',diminished:'Diminuto'}[c.quality];}
$('key').onchange=()=>{selected=0;render();};$('major').onclick=()=>{mode='major';selected=0;render();};$('minor').onclick=()=>{mode='minor';selected=0;render();};render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_harmonic_field',title:'Definir campo harmônico',description:'Seleciona o tom, o modo e um grau no explorador de campo harmônico.',inputSchema:{type:'object',properties:{key:{type:'string',enum:Music.keys},mode:{type:'string',enum:['major','minor']},degree:{type:'integer',minimum:1,maximum:7}},required:['key','mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Music.keys.includes(input.key)||!['major','minor'].includes(input.mode)||(input.degree!==undefined&&(!Number.isInteger(input.degree)||input.degree<1||input.degree>7)))throw new Error('Tom, modo ou grau inválido.');$('key').value=input.key;mode=input.mode;selected=(input.degree??1)-1;render();const f=Music.field(input.key,mode);return{key:f.key,mode,notes:f.notes,chords:f.chords.map(c=>c.symbol),selectedChord:f.chords[selected].symbol};}},{signal:lifecycle.signal})).catch(()=>{});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
